-- Razorfen Kraul: creature abilities
-- Most of the dungeon's creatures (the Razorfen quilboar, the Death's Head cultists, the boars and bats) had no AI or ran classic rows. Cataclysm left these classic dungeons
-- largely as they were, so port their abilities from the classic (AzerothCore) data first, with its dungeon flags and spell-set
-- phases, falling back to the Cataclysm data; rows needing events, actions or action lists LoA lacks are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '4421,4422,4424,4425,4428,4435,4436,4437,4442,4511,4512,4514,4517,4520,4523,4525,4538,4541,4842,6168';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
